{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    required = ("nodes", "core_distance", "distances")
    for field in required:
        if field not in case:
            raise ValueError("missing required field: " + field)

    nodes = case["nodes"]
    core = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) or not node for node in nodes):
        raise ValueError("node IDs must be non-empty strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node IDs must be unique")
    if not isinstance(core, dict):
        raise ValueError("core_distance must be an object")
    if set(core) != set(nodes):
        raise ValueError("core_distance must contain exactly the registered nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_number(value):
        return (isinstance(value, (int, float)) and
                not isinstance(value, bool) and
                math.isfinite(value) and value >= 0)

    normalized_core = {}
    for node in nodes:
        value = core[node]
        if not valid_number(value):
            raise ValueError("core distances must be finite non-negative numbers")
        normalized_core[node] = float(value)

    node_set = set(nodes)
    seen = set()
    weighted_edges = []
    for item in distances:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("each distance must be [left, right, value]")
        left, right, distance = item
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not a registered node")
        if left == right:
            raise ValueError("self distances are not allowed")
        if not valid_number(distance):
            raise ValueError("distances must be finite non-negative numbers")
        if right < left:
            left, right = right, left
        pair = (left, right)
        if pair in seen:
            raise ValueError("duplicate undirected distance")
        seen.add(pair)
        reachability = max(normalized_core[left], normalized_core[right], float(distance))
        weighted_edges.append((reachability, left, right))

    weighted_edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right] or (rank[root_left] == rank[root_right] and root_right < root_left):
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    selected = []
    total = 0.0
    for weight, left, right in weighted_edges:
        if union(left, right):
            selected.append([left, right, weight])
            total += weight
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {"edges": selected, "total_weight": total}
